//! Formats a plan as Rust source.

use std::fmt::Write;

use turbojet_dictionary::Dictionary;

use crate::plan::{Plan, Presence, Slot, Struct};

/// Why writing generated code can't fail: it goes into a `String`.
const INFALLIBLE: &str = "writing to a String cannot fail";

pub(crate) fn root(dict: &Dictionary) -> String {
    format!(
        "//! Generated by turbojet-codegen from the {} dictionary. Don't edit: regenerate.\n\n\
         pub mod enums;\npub mod groups;\npub mod messages;\npub mod tags;\n\n\
         pub use enums::*;\npub use groups::*;\npub use messages::*;\n",
        dict.version()
    )
}

pub(crate) fn tags(plan: &Plan) -> String {
    let mut out = String::from("//! Tag numbers, one per dictionary field.\n\n");
    for (constant, name, tag) in &plan.tags {
        writeln!(out, "/// {name}({tag}).\npub const {constant}: u32 = {tag};").expect(INFALLIBLE);
    }
    out
}

pub(crate) fn enums(plan: &Plan) -> String {
    let mut out = String::from("//! Enumerated fields.\n");
    for e in &plan.enums {
        out.push_str("\nturbojet::fix_enum! {\n");
        doc_comment(&mut out, "    ", &e.doc);
        writeln!(out, "    {} {{", e.name).expect(INFALLIBLE);
        for v in &e.variants {
            if let Some(doc) = &v.doc {
                doc_comment(&mut out, "        ", doc);
            }
            writeln!(out, "        {} = {:?},", v.name, v.code).expect(INFALLIBLE);
        }
        out.push_str("    }\n}\n");
    }
    out
}

pub(crate) fn groups(plan: &Plan) -> String {
    let mut out = String::from("//! Repeating-group entries.\n");
    out.push_str(&imports(plan, &plan.groups.iter().collect::<Vec<_>>(), false));
    in_parts(&mut out, &plan.groups, |out, group| {
        write_struct(out, "fix_group", &format!("{} / {}", group.name, group.ref_name), group);
    });
    out
}

pub(crate) fn messages(plan: &Plan) -> String {
    let mut out = String::from("//! Application messages.\n");
    let defs: Vec<&Struct> = plan.messages.iter().map(|m| &m.def).collect();
    out.push_str(&imports(plan, &defs, true));
    in_parts(&mut out, &plan.messages, |out, m| {
        write_struct(out, "fix_message", &format!("{} / {} = {:?}", m.def.name, m.def.ref_name, m.msg_type), &m.def);
    });
    out
}

/// How many modules a file's groups or messages are spread over. rustc puts a module's code in
/// one codegen unit, optimised on one thread, so a version's messages in one module made a
/// release build mostly serial: FIX 5.0 SP2's took 96 s, against 48 s split.
const PARTS: usize = 16;

/// Writes `items` into up to [`PARTS`] private modules of at least 8 items, each re-exported.
fn in_parts<T>(out: &mut String, items: &[T], mut write: impl FnMut(&mut String, &T)) {
    for (i, part) in items.chunks(items.len().div_ceil(PARTS).max(8)).enumerate() {
        writeln!(out, "\nmod part{i} {{\n    use super::*;").expect(INFALLIBLE);
        for item in part {
            write(out, item);
        }
        writeln!(out, "}}\npub use part{i}::*;").expect(INFALLIBLE);
    }
}

/// The `use` lines the structs need, and no more (unused imports would warn).
fn imports(plan: &Plan, structs: &[&Struct], groups_module: bool) -> String {
    let slots = || structs.iter().flat_map(|s| &s.slots);
    let mut out = String::from("\n");
    // The type names in a slot's type, e.g. `Vec`, `Code` and `Side` in `Vec<Code<Side>>`.
    let names = || slots().flat_map(|s| s.ty.split(['<', '>', ' ', ',']).filter(|name| !name.is_empty()));
    if names().any(|name| plan.enums.iter().any(|e| e.name == name)) {
        out.push_str("use super::enums::*;\n");
    }
    if groups_module && slots().any(|s| s.presence.is_group()) {
        out.push_str("use super::groups::*;\n");
    }
    if !structs.is_empty() {
        out.push_str("use super::tags::*;\n");
    }
    const FIELD_TYPES: [&str; 10] = [
        "Code",
        "CompactString",
        "Decimal",
        "MonthYear",
        "NaiveDate",
        "Secret",
        "TzTimeOnly",
        "TzTimestamp",
        "UtcTimeOnly",
        "UtcTimestamp",
    ];
    let types: Vec<&str> = FIELD_TYPES.into_iter().filter(|t| names().any(|name| name == *t)).collect();
    match types.as_slice() {
        [] => {}
        [one] => writeln!(out, "use turbojet::fields::{one};").expect(INFALLIBLE),
        many => writeln!(out, "use turbojet::fields::{{{}}};", many.join(", ")).expect(INFALLIBLE),
    }
    out
}

fn write_struct(out: &mut String, macro_name: &str, head: &str, s: &Struct) {
    writeln!(out, "\nturbojet::{macro_name}! {{").expect(INFALLIBLE);
    doc_comment(out, "    ", &s.doc);
    writeln!(out, "    {head} {{").expect(INFALLIBLE);
    for slot in &s.slots {
        doc_comment(out, "        ", &slot.doc);
        let tags = match &slot.length {
            Some(length) => format!("{length} => {}", slot.tag),
            None => slot.tag.clone(),
        };
        writeln!(out, "        {}: {} {} = {tags},", slot.ident, slot.presence.keyword(), slot.ty).expect(INFALLIBLE);
    }
    out.push_str("    }\n}\n");

    write_new(out, s);
}

/// A `///` line per line of `doc`; an empty line separates paragraphs.
fn doc_comment(out: &mut String, indent: &str, doc: &str) {
    for line in doc.lines() {
        if line.is_empty() {
            writeln!(out, "{indent}///").expect(INFALLIBLE);
        } else {
            writeln!(out, "{indent}/// {line}").expect(INFALLIBLE);
        }
    }
}

/// A required slot's type as `new` takes it.
fn required_type(slot: &Slot) -> Option<String> {
    match slot.presence {
        Presence::Req | Presence::Data => Some(slot.ty.clone()),
        Presence::ReqGroup => Some(format!("Vec<{}>", slot.ty)),
        Presence::Opt | Presence::Group | Presence::OptData => None,
    }
}

/// `new`, from the required fields and groups. With two or more, they come in a struct of their
/// own, `NameRequired`, so each is named where it's given: positional arguments of one type (the
/// IDs, or LeavesQty, CumQty and AvgPx) could be swapped and still compile. One is taken as it is.
fn write_new(out: &mut String, s: &Struct) {
    let required: Vec<(&Slot, String)> = s.slots.iter().filter_map(|f| required_type(f).map(|ty| (f, ty))).collect();
    let inits: Vec<String> = s
        .slots
        .iter()
        .map(|f| match f.presence {
            Presence::Req | Presence::ReqGroup | Presence::Data => f.ident.clone(),
            Presence::Opt | Presence::OptData => format!("{}: None", f.ident),
            Presence::Group => format!("{}: Vec::new()", f.ident),
        })
        .collect();
    let name = &s.name;
    let inits = inits.join(", ");
    let into = |f: &Slot| f.ty == "CompactString" || f.ty == "Secret" || f.ty.starts_with("Code<");
    match required.as_slice() {
        [] | [_] => {
            let params: Vec<String> = required
                .iter()
                .map(
                    |(f, ty)| {
                        if into(f) { format!("{}: impl Into<{ty}>", f.ident) } else { format!("{}: {ty}", f.ident) }
                    },
                )
                .collect();
            let converted: Vec<String> = required
                .iter()
                .filter(|(f, _)| into(f))
                .map(|(f, _)| format!("let {0} = {0}.into();", f.ident))
                .collect();
            let what = if required.is_empty() { "No required fields" } else { "With its required field" };
            write!(
                out,
                "\nimpl {name} {{\n    /// {what}; optional ones empty.\n    \
                 #[allow(clippy::new_without_default)]\n    \
                 pub fn new({params}) -> Self {{\n        {converted}Self {{ {inits} }}\n    }}\n}}\n",
                params = params.join(", "),
                converted = converted.iter().map(|c| format!("{c}\n        ")).collect::<String>(),
            )
            .expect(INFALLIBLE);
        }
        _ => {
            writeln!(out, "\n/// [`{name}`]'s required fields and groups, for [`{name}::new`].").expect(INFALLIBLE);
            writeln!(out, "#[derive(Debug, Clone, PartialEq)]\npub struct {name}Required {{").expect(INFALLIBLE);
            for (slot, ty) in &required {
                doc_comment(out, "    ", &slot.doc);
                writeln!(out, "    pub {}: {ty},", slot.ident).expect(INFALLIBLE);
            }
            let fields: Vec<&str> = required.iter().map(|(f, _)| f.ident.as_str()).collect();
            write!(
                out,
                "}}\n\nimpl {name} {{\n    /// With the required fields and groups; optional ones empty.\n    \
                 pub fn new(required: {name}Required) -> Self {{\n        \
                 let {name}Required {{ {fields} }} = required;\n        Self {{ {inits} }}\n    }}\n}}\n",
                fields = fields.join(", "),
            )
            .expect(INFALLIBLE);
        }
    }
}
